DEFAULT_MODELS_VALUES: dict[str, Any] = {
    "mode": "openai",
    "prompt_style": "chat",
    "tokenizer_mode": "default",
    "enabled": True,
    "context_window": 128_000,
    "support_image": 1,
    "support_audio": 0,
    "support_tools": True,
    "support_reasoning": True,
    "api_type": "chat_completions",
}

DEFAULT_DISCOVERY_TIMEOUT = 3.0

logger = logging.getLogger(__name__)


def _capability_supported(capability: Any, default: bool) -> bool:
    if capability is None:
        return default

    supported = getattr(capability, "supported", None)
    if supported is not None:
        return bool(supported)

    if isinstance(capability, Mapping):
        return bool(capability.get("supported", default))

    return bool(capability)


def _capability_count(capability: Any, default_supported: bool) -> int | None:
    if not _capability_supported(capability, default_supported):
        return None

    maximum = getattr(capability, "maximum", None)
    if isinstance(capability, Mapping):
        maximum = capability.get("maximum", maximum)

    return positive_int(maximum) or 1


def _check_tokenizer_mode(
    model_info: ModelInfoOutput, tokenizer_mode: str, **kwargs: Any
) -> bool:
    try:
        tokenizer = get_tokenizer(tokenizer_mode, model_info.id, **kwargs)
        tokens = tokenizer.encode("Test tokenizer support", add_special_tokens=False)
    except Exception as exc:
        logger.warning(
            "This provider don't support %s mode for model '%s': %s",  # TODO: add link to dos
            tokenizer_mode,
            model_info.id,
            exc,
        )
        return False
    return bool(tokens)


def _probe_chat_completions_endpoint(
    api_base: str, api_key: str | None, model_id: str, timeout: float
) -> bool:
    """Return True if the chat/completions endpoint responds (non-404)."""
    import requests

    url = api_base.rstrip("/") + "/chat/completions"
    headers: dict[str, str] = {"Content-Type": "application/json"}
    if api_key:
        headers["Authorization"] = f"Bearer {api_key}"
    payload = {
        "model": model_id,
        "messages": [{"role": "user", "content": "test"}],
        "max_tokens": 1,
    }
    try:
        resp = requests.post(url, json=payload, headers=headers, timeout=timeout)
        return resp.status_code != 404
    except Exception as exc:
        logger.debug("Chat completions probe failed for %s: %s", api_base, exc)
        # Cannot reach server — conservatively assume the endpoint exists.
        return True


def _probe_responses_endpoint(
    api_base: str, api_key: str | None, model_id: str, timeout: float
) -> bool:
    """Return True if the responses endpoint responds (non-404)."""
    import requests

    url = api_base.rstrip("/") + "/responses"
    headers: dict[str, str] = {"Content-Type": "application/json"}
    if api_key:
        headers["Authorization"] = f"Bearer {api_key}"
    payload = {
        "model": model_id,
        "input": "test",
        "max_output_tokens": 1,
    }
    try:
        resp = requests.post(url, json=payload, headers=headers, timeout=timeout)
        return resp.status_code != 404
    except Exception as exc:
        logger.debug("Responses API probe failed for %s: %s", api_base, exc)
        return False


def _get_openai_api_type_for_model(model_id: str) -> str:
    """Return the api_type for a real OpenAI model using llama-index's model registry.

    Models in RESPONSES_API_ONLY_MODELS (e.g. gpt-5.2-pro) must use the
    Responses API; all others default to chat_completions.
    """
    try:
        from llama_index.llms.openai.utils import (  # ty:ignore[unresolved-import]
            is_chatcomp_api_supported,
        )

        return (
            "chat_completions" if is_chatcomp_api_supported(model_id) else "responses"
        )
    except ImportError:
        return "chat_completions"


def _probe_api_type(
    model_infos: list[ModelInfoOutput],
    api_base: str,
    api_key: str | None,
    timeout: float = DEFAULT_DISCOVERY_TIMEOUT,
) -> str:
    """Detect which API type an OpenAI-compatible endpoint supports.

    Probes chat/completions first; if that returns 404, falls back to responses.
    This function is only called for non-OpenAI endpoints — real OpenAI uses
    ``_get_openai_api_type_for_model`` per model instead.
    """
    if not model_infos:
        return str(DEFAULT_MODELS_VALUES["api_type"])

    model_id = model_infos[0].id

    if _probe_chat_completions_endpoint(api_base, api_key, model_id, timeout):
        logger.debug("Detected chat_completions API type for %s", api_base)
        return "chat_completions"

    if _probe_responses_endpoint(api_base, api_key, model_id, timeout):
        logger.info(
            "chat/completions endpoint not found for %s; using Responses API", api_base
        )
        return "responses"

    logger.debug(
        "Could not detect API type for %s, defaulting to chat_completions", api_base
    )
    return str(DEFAULT_MODELS_VALUES["api_type"])


def _model_info_to_config(
    model_info: ModelInfoOutput,
    tokenizer_mode: str,
    mode: str | None = None,
    provider: str | None = None,
    api_type: str = "chat_completions",
) -> LLMModelConfig:
    from private_gpt.settings.settings import LLMModelConfig, SamplingParams

    capabilities = model_info.capabilities
    supports_reasoning = DEFAULT_MODELS_VALUES["support_reasoning"]
    supports_tools = DEFAULT_MODELS_VALUES["support_tools"]
    support_image: int | None = DEFAULT_MODELS_VALUES["support_image"]
    support_audio: int | None = DEFAULT_MODELS_VALUES["support_audio"]

    if capabilities is not None:
        supports_reasoning = _capability_supported(
            capabilities.thinking, supports_reasoning
        ) or _capability_supported(capabilities.effort, supports_reasoning)
        supports_tools = _capability_supported(
            capabilities.structured_outputs, supports_tools
        )
        support_image = _capability_count(capabilities.image_input, bool(support_image))
        support_audio = _capability_count(capabilities.audio_input, bool(support_audio))

    # Default privateGPT values
    mode = mode or DEFAULT_MODELS_VALUES["mode"]
    prompt_style = DEFAULT_MODELS_VALUES["prompt_style"]

    max_new_tokens = positive_int(model_info.max_tokens)
    sampling_params = (
        SamplingParams(max_new_tokens=max_new_tokens)
        if max_new_tokens is not None
        else SamplingParams()
    )

    return LLMModelConfig(
        name=model_info.id,
        mode=mode,
        provider=provider,
        prompt_style=prompt_style,
        tokenizer_mode=tokenizer_mode,
        enabled=True,
        alias=model_info.id,
        api_type=api_type,
        context_window=positive_int(model_info.max_input_tokens)
        or DEFAULT_MODELS_VALUES["context_window"],
        support_image=support_image,
        support_audio=support_audio,
        support_tools=supports_tools,
        support_reasoning=supports_reasoning,
        sampling_params=sampling_params,
        reasoning_sampling_params=sampling_params,
    )


def _get_tokenizer_mode(
    model_infos: list[ModelInfoOutput],
    api_base: str,
    api_key: str | None,
) -> str:
    if not model_infos:
        return str(DEFAULT_MODELS_VALUES["tokenizer_mode"])

    first_model = model_infos[0]
    if _check_tokenizer_mode(
        first_model,
        "remote",
        api_base=api_base,
        api_key=api_key,
    ):
        return "remote"

    return str(DEFAULT_MODELS_VALUES["tokenizer_mode"])


def get_models(
    api_base: str,
    api_key: str | None,
    *,
    mode: str | None = None,
    timeout: float = DEFAULT_DISCOVERY_TIMEOUT,
    fetch_all_pages: bool = True,
    force_model_kind: bool = False,
) -> list[LLMModelConfig]:
    from private_gpt.components.model_discovery.url_utils import is_openai_api_base

    discovery = discover_model_infos(
        api_base,
        api_key,
        force_kind=ModelKind.LLM if force_model_kind else None,
        timeout=timeout,
        fetch_all_pages=fetch_all_pages,
    )
    model_infos = list(discovery.llm_models)
    tokenizer_mode = _get_tokenizer_mode(
        model_infos,
        api_base=api_base,
        api_key=api_key,
    )

    # For real OpenAI, determine api_type per model (some models are responses-only).
    # For other endpoints, probe once and apply the result to all models.
    use_per_model_openai = is_openai_api_base(api_base)
    probed_api_type: str | None = None
    if not use_per_model_openai:
        probed_api_type = _probe_api_type(model_infos, api_base, api_key, timeout)

    configs: list[LLMModelConfig] = []
    for model_info in model_infos:
        api_type = (
            _get_openai_api_type_for_model(model_info.id)
            if use_per_model_openai
            else (probed_api_type or str(DEFAULT_MODELS_VALUES["api_type"]))
        )
        configs.append(
            _model_info_to_config(
                model_info,
                tokenizer_mode=tokenizer_mode,
                mode=mode,
                provider=discovery.provider.value,
                api_type=api_type,
            )
        )

    return configs

import logging
from collections.abc import Callable, Iterator
from typing import Any

from injector import inject, singleton
from llama_index.core.base.llms.types import LLMMetadata
from llama_index.core.llms import LLM

from private_gpt.components.llm.custom.base import ZylonLLM
from private_gpt.components.llm.discovery import get_models
from private_gpt.components.llm.factories.registry import LLMFactoryRegistry
from private_gpt.components.llm.llm_helper import (
    AsyncTokenizerFn,
    TokenizerFn,
    get_async_tokenizer_fn,
    get_tokenizer_fn,
)
from private_gpt.components.llm.registry import LLMInstance, LLMRegistry
from private_gpt.components.llm.tokenizers.tokenizer_base import (
    AsyncTokenizerBase,
    TokenizerBase,
)
from private_gpt.components.model_discovery.service import are_distinct_api_bases
from private_gpt.settings.settings import LLMModelConfig, Settings

logger = logging.getLogger(__name__)


@singleton
class LLMComponent:
    @inject
    def __init__(self, settings: Settings, llm_registry: LLMRegistry) -> None:
        self.registry = llm_registry
        self.settings = settings

        self.factory_registry = LLMFactoryRegistry(settings)
        self.llm_models = {
            model.name: model
            for model in self.settings.models
            if model.type == "llm" and model.enabled
        }
        self._default_model_id = settings.llm.default_model

        self._initialize_models()

    def _discover_models(self) -> list[LLMModelConfig]:
        if not self.settings.llm.auto_discover_models:
            return []

        return get_models(
            self.settings.openai.api_base,
            self.settings.openai.api_key,
            force_model_kind=are_distinct_api_bases(
                self.settings.openai.embedding_api_key,
                self.settings.openai.embedding_api_base,
            ),
        )

    def _initialize_models(self) -> None:
        for model in self._discover_models():
            if model.name not in self.llm_models:
                self.llm_models[model.name] = model

        if not self.llm_models:
            logger.warning(
                "No LLM models are configured, "
                "or it was impossible to discover any models from the API"
            )

        registered_model_ids: list[str] = []
        for model_id, model_config in list(self.llm_models.items()):
            try:
                logger.info(
                    "Initializing LLM model '%s' with mode='%s'",
                    model_id,
                    model_config.mode,
                )

                factory = self.factory_registry.get_factory(model_config.mode)
                instance = factory.create_llm(model_config)

                alias = instance.alias
                aliases = [alias] if alias and alias != model_id else []
                if model_id == self._default_model_id:
                    aliases.append(LLMRegistry.default())

                registry_instance = LLMInstance(
                    llm=instance.llm, tokenizer=instance.tokenizer
                )
                self.registry.register(model_id, registry_instance, aliases=aliases)
                registered_model_ids.append(model_id)

                logger.info("Successfully registered LLM model '%s'", model_id)

            except Exception as e:
                self.llm_models.pop(model_id, None)
                if model_id == self._default_model_id:
                    raise ValueError(
                        f"Default LLM model '{model_id}' could not be initialized: {e}"
                    ) from e
                logger.warning(
                    "Skipping unavailable LLM model '%s': %s",
                    model_id,
                    e,
                )

        if not self._default_model_id and registered_model_ids:
            self._default_model_id = next(iter(self.llm_models))
            logger.warning(
                "No default LLM model configured. Auto-selecting: '%s'",
                self._default_model_id,
            )

        if self._default_model_id:
            default_instance = self.registry.get(self._default_model_id)
            if not default_instance:
                raise ValueError(
                    f"Default model '{self._default_model_id}' not found in registered models"
                )

            if not self.registry.get(LLMRegistry.default()):
                self.registry.register(LLMRegistry.default(), default_instance)

            logger.info("Set default model to '%s'", self._default_model_id)

    def get_llm(self, model_id: str | None = None) -> LLM:
        target_model = model_id or self._default_model_id

        if not target_model:
            raise ValueError("No model specified and no models are configured")

        llm_instance = self.registry.get(target_model)
        if not llm_instance:
            available = self.registry.get_all_aliases()
            raise ValueError(
                f"Model '{target_model}' not found. Available: {available}"
            )

        return llm_instance.llm

    def get_alias(self, model_id: str | None = None) -> str | None:
        target_model = model_id or self._default_model_id
        if not target_model:
            return None
        aliases = self.registry.get_aliases(target_model)
        return aliases.pop() if aliases else None

    def get_config(self, model_id: str | None = None) -> LLMModelConfig:
        target_model = model_id or self._default_model_id

        if not target_model:
            raise ValueError("No model specified and no models are configured")

        model_config = self.llm_models.get(target_model)
        if not model_config:
            available = list(self.llm_models.keys())
            for alias in self.registry.get_aliases(target_model):
                if alias in self.llm_models:
                    model_config = self.llm_models[alias]
                    return model_config

            raise ValueError(
                f"Model config '{target_model}' not found. Available: {available}"
            )

        return model_config

    def get_tokenizer(self, model_id: str | None = None) -> TokenizerBase | None:
        target_model = model_id or self._default_model_id

        if not target_model:
            raise ValueError("No model specified and no models are configured")

        llm_instance = self.registry.get(target_model)
        if not llm_instance:
            available = self.registry.get_all_aliases()
            raise ValueError(
                f"Model '{target_model}' not found. Available: {available}"
            )

        tokenizer = llm_instance.tokenizer
        return tokenizer

    def filter(
        self, predicate: Callable[[LLM, LLMModelConfig], bool]
    ) -> Iterator[tuple[LLM, LLMModelConfig, TokenizerFn | AsyncTokenizerFn | None]]:
        """Filter LLM components based on a predicate function.

        :param predicate: A function that takes an LLM
         and returns True if it matches the criteria.
        :return: An iterator over the filtered LLM components.
        """
        seen = set()
        for model_id, component in self.registry._registry.items():
            model_config = self.llm_models.get(model_id)
            if (
                model_config
                and id(model_id) not in seen
                and predicate(component.llm, model_config)
            ):
                seen.add(id(model_id))

                tokenizer_fn: TokenizerFn | AsyncTokenizerFn | None = None
                if component.tokenizer:
                    if isinstance(component.tokenizer, AsyncTokenizerBase):
                        tokenizer_fn = get_async_tokenizer_fn(component.tokenizer)
                    else:
                        tokenizer_fn = get_tokenizer_fn(component.tokenizer)
                yield component.llm, model_config, tokenizer_fn

    @property
    def llm(self) -> LLM:
        return self.get_llm()

    @llm.setter
    def llm(self, value: LLM) -> None:
        if not self._default_model_id:
            raise ValueError("No default model configured to set LLM")

        before_tokenizer: TokenizerBase | None = None
        llm_instance = self.registry.get(self._default_model_id)
        if llm_instance:
            before_tokenizer = llm_instance.tokenizer
            self.registry.unregister(self._default_model_id)

        instance = LLMInstance(llm=value, tokenizer=before_tokenizer)
        logger.warning(
            "Directly setting the LLM instance is deprecated. "
            "Use ONLY for testing purposes."
        )
        self.registry.register(self._default_model_id, instance)

    @property
    def alias(self) -> str | None:
        return self.get_alias()

    @property
    def tokenizer(self) -> TokenizerBase | None:
        return self.get_tokenizer()

    def metadata(self, model_id: str | None = None, **kwargs: Any) -> LLMMetadata:
        llm = self.get_llm(model_id)
        llm_metadata: Any = (
            llm.get_metadata(**kwargs) if isinstance(llm, ZylonLLM) else llm.metadata
        )
        return llm_metadata  # type: ignore[no-any-return]

